// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // Fuzz the caller address — the property: owner() should always equal the originally stored owner (address(this))
    function testFuzz_property(address caller) public {
        // Keep domain wide but exclude zero address just to avoid degenerate EOA/constructor confusion
        // (still a wide domain so mutant can be found)
        vm.assume(caller != address(0));

        // Call owner() as the fuzzed caller
        bool ok;
        address observed;
        // Use prank to simulate the caller
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = true;
            observed = o;
        } catch {
            ok = false;
            observed = address(0);
        }

        // The universal property: for any caller, the contract's owner() must return the deployer (address(this))
        // This holds for the reference implementation for all callers, but the mutant (which returns msg.sender)
        // will fail when caller != address(this).
        assertTrue(ok && observed == address(this));
    }
}

