        // general rule: owner() should always return the constructor-set owner (address(this) from setUp)
        // mutant: owner() returns msg.sender for some callers, breaking the rule
        // we must observe c only via its public surface. Call owner() as `caller` and compare to stored owner getter.

        // ensure fuzzed address is not zero to keep wide but sensible domain
        vm.assume(caller != address(0));

        // call owner() as the fuzzed caller
        bool ok;
        address returned;
        vm.prank(caller);
        try c.owner() returns (address r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
            returned = address(0);
        }

        // the reference contract always returns the stored owner (constructor arg address(this)) for any caller
        // assert that either the call reverted (shouldn't) or the returned owner equals the stored owner getter
        // This single assertion will hold for the reference, but the mutant (which returns msg.sender) will fail
        // for some caller values (when caller != stored owner).
        address stored = c.owner(); // reading via our current context; in reference this equals the constructor owner

        // exactly one assertion as required: check that if call succeeded, returned == stored; if call reverted, consider that a failure
        assertTrue(ok && returned == stored);
    }
