import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    function testFuzz_property(address recipient) public {
        // Keep domain wide: allow any address (including zero)
        // Call as owner (setUp deployed contract with owner == address(this))
        bool ok;
        try c.setRewardsRecipient(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): after calling setRewardsRecipient(recipient),
        // the contract's public getter rewardsRecipient() must equal the provided recipient.
        // The correct reference implementation always stores the value; the mutant omits the assignment
        // and will therefore fail this assertion for some inputs.
        assertTrue(ok && (c.rewardsRecipient() == recipient));
    }
}

// Minimal interfaces needed for constructor types
interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface ICVXBooster {
    struct PoolInfo { address lptoken; address token; address gauge; address crvRewards; address stash; bool shutdown; }
    function poolInfo(uint256 _pid) external view returns (PoolInfo memory);
    function depositAll(uint256 _pid, bool _stake) external returns (bool);
    function withdrawAll(uint256 _pid) external returns (bool);
    function deposit(uint256 _pid, uint256 _amount, bool _stake) external returns (bool);
    function withdraw(uint256 _pid, uint256 _amount) external returns (bool);
}

