import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    function testFuzz_property(address recipient) public {
        // keep domain wide; no assumptions so fuzzer can try any address
        // Call setRewardsRecipient as the owner (setUp deployed c with owner == this)
        // Use try/catch pattern to satisfy rules if it could revert (it shouldn't)
        bool ok;
        try c.setRewardsRecipient(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always stores the recipient so the getter equals the input.
        // The mutant emits the event but does not store the value, so for some input this will fail.
        assertTrue(ok && c.rewardsRecipient() == recipient);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address recipient) public {
        // keep wide domain; no tight assumptions
        // Call setRewardsRecipient with the fuzzed address and then assert that the getter equals it.
        // This holds for the reference implementation (it assigns rewardsRecipient = _recipeint)
        // and will fail for the mutant that only emits the event but does not assign.
        // Use prank to call as owner (setUp constructor set owner to this), so msg.sender == owner
        vm.prank(address(this));
        c.setRewardsRecipient(recipient);

        // exactly one assertion reading c's public getter
        assertTrue(c.rewardsRecipient() == recipient);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    function testFuzz_property(address candidate) public {
        // Keep domain wide; no assumptions so fuzz can pick zero and non-zero addresses

        // Call setRewardsRecipient with the fuzzed candidate
        // Use prank to call as owner (setUp used address(this) as owner)
        vm.prank(address(this));
        c.setRewardsRecipient(candidate);

        // The general rule: after the call, c.rewardsRecipient() == candidate
        // This holds for the reference implementation for all inputs.
        // The mutant that ignores non-zero inputs will fail this assertion for some candidate (any non-zero address).
        assertTrue(c.rewardsRecipient() == candidate);
    }
}
